import{_ as a,o as t,c as i,a0 as n}from"./chunks/framework.CzVS_xMp.js";const u=JSON.parse('{"title":"Lab: Gradient Bucketing, Fusion, and Compression","description":"","frontmatter":{},"headers":[],"relativePath":"systems-performance/labs/ch04/gradient-bucketing/index.md","filePath":"systems-performance/labs/ch04/gradient-bucketing/index.md","lastUpdated":1788490169000}'),s={name:"systems-performance/labs/ch04/gradient-bucketing/index.md"};function o(r,e,d,h,c,l){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="lab-gradient-bucketing-fusion-and-compression" tabindex="-1">Lab: Gradient Bucketing, Fusion, and Compression <a class="header-anchor" href="#lab-gradient-bucketing-fusion-and-compression" aria-label="Permalink to &quot;Lab: Gradient Bucketing, Fusion, and Compression&quot;">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Show why Chapter 4 treats gradient synchronization as both a bandwidth problem and a launch-latency problem.</p><p>This lab adapts the important ideas behind gradient fusion and gradient compression benchmarks.</p><h2 id="baseline" tabindex="-1">Baseline <a class="header-anchor" href="#baseline" aria-label="Permalink to &quot;Baseline&quot;">​</a></h2><p>The baseline sends many small FP32 gradient buckets. This preserves precision, but every bucket pays a fixed communication launch cost.</p><h2 id="optimized" tabindex="-1">Optimized <a class="header-anchor" href="#optimized" aria-label="Permalink to &quot;Optimized&quot;">​</a></h2><p>The optimized path fuses buckets into one contiguous buffer and transfers it as FP16. This reduces both launch count and communication bytes. The reduced-precision checksum is compared with a tolerance instead of exact equality.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare.py</span></span></code></pre></div><h2 id="expected-observation" tabindex="-1">Expected Observation <a class="header-anchor" href="#expected-observation" aria-label="Permalink to &quot;Expected Observation&quot;">​</a></h2><p>The optimized path should have fewer launches, fewer transferred bytes, lower modelled communication time, and a close output checksum.</p><h2 id="what-this-proves" tabindex="-1">What This Proves <a class="header-anchor" href="#what-this-proves" aria-label="Permalink to &quot;What This Proves&quot;">​</a></h2><p>Gradient fusion and compression are useful when transfer latency or network bandwidth is exposed. They are not free: the precision error must be measured against the training tolerance.</p>',14)])])}const b=a(s,[["render",o]]);export{u as __pageData,b as default};
